#!/usr/bin/env bash
set -uo pipefail

# Test: connect-tier connector skills keep their upsell gate while the official
#       Notion MCP path stays available in OSS without private connector code.
# Generated by /qa on 2026-08-07 for the notion upsell + ingestion QA pass.
# Covers: .claude/skills/{notion-connect,ingest-notion}/SKILL.md, CLAUDE.md
#         mode rules, rendered specs, runtime bundles, connect pack.

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; return 0; }

echo "test-notion-upsell-gate"
echo ""

COPY="You can expand your knowledge base with connections to Notion, Google Drive, Docs, Sheets, and many more. Upgrade to Connected Tier to accelerate."

for f in ".claude/skills/teams-connect/SKILL.md"; do
  # 1. Verbatim copy survives, on one line.
  if grep -qF "$COPY" "$ROOT/$f"; then
    pass "$f: verbatim upsell copy intact"
  else
    fail "$f: upsell copy missing or reworded/rewrapped"
  fi

  # 2. The gate precedes the executable flow (preamble references are fine;
  #    the flow sections must sit below the gate).
  GATE_LINE=$(grep -n "OSS tier" "$ROOT/$f" | head -1 | cut -d: -f1)
  FLOW_LINE=$(grep -nE "^## (Setup flow|Curated mode|Mode routing|Bulk mode|Step 0)" "$ROOT/$f" | head -1 | cut -d: -f1)
  if [ -n "$GATE_LINE" ] && [ -n "$FLOW_LINE" ] && [ "$GATE_LINE" -lt "$FLOW_LINE" ]; then
    pass "$f: gate (line $GATE_LINE) precedes executable flow (line $FLOW_LINE)"
  else
    fail "$f: gate does not precede the executable flow" "gate=$GATE_LINE flow=$FLOW_LINE"
  fi

  # 3. Sanctioned upgrade path + hard stop on decline.
  if grep -q "egregore connect" "$ROOT/$f" && grep -qi "stop" "$ROOT/$f"; then
    pass "$f: egregore connect path + stop semantics present"
  else
    fail "$f: upgrade path or decline stop missing"
  fi

  # 4. The gate's tier predicate states the CANONICAL truth table:
  #    local iff mode=="local" OR api_url empty (matches _detect_mode).
  if grep -q '`MODE` is `local` \*\*or\*\* `API_URL` is empty' "$ROOT/$f"; then
    pass "$f: tier predicate matches canonical _detect_mode"
  else
    fail "$f: tier predicate drifted from canonical mode detection"
  fi
done

# Notion moved to the official hosted MCP and must not inherit the Connect
# upsell or call the retained private REST connector.
for f in ".claude/skills/notion-connect/SKILL.md" ".claude/skills/ingest-notion/SKILL.md"; do
  if ! grep -qF "$COPY" "$ROOT/$f"; then
    pass "$f: no Connected-tier upsell on official Notion MCP"
  else
    fail "$f: stale Connected-tier upsell remains"
  fi
  if ! grep -q 'connector-notion\.sh' "$ROOT/$f"; then
    pass "$f: no dependency on retained REST connector"
  else
    fail "$f: still invokes retained REST connector"
  fi
done

# 5. CLAUDE.md sanctions exactly this flow, and every rendered runtime spec
#    carries it (Codex, Pi, Prime).
if grep -q "one sanctioned upgrade path is \`egregore connect\`" "$ROOT/CLAUDE.md"; then
  pass "CLAUDE.md: egregore connect is the sanctioned upgrade path"
else
  fail "CLAUDE.md: sanctioned-upgrade-path rule missing"
fi
for spec in "AGENTS.md" ".pi/APPEND_SYSTEM.md" ".prime/agent/APPEND_SYSTEM.md"; do
  if [ -f "$ROOT/$spec" ] && grep -q "egregore connect" "$ROOT/$spec"; then
    pass "$spec: carries the sanctioned upgrade path"
  else
    fail "$spec: missing the upgrade-path rule (re-render specs)"
  fi
done

# 6. OSS bundles ship the skills — and never the legacy connector code.
for runtime in codex pi prime; do
  BUNDLE="$ROOT/packages/create-egregore/runtime/$runtime"
  [ -d "$BUNDLE" ] || { fail "runtime/$runtime bundle missing"; continue; }
  if [ -n "$(find "$BUNDLE" -type d -name notion-connect 2>/dev/null)" ] \
     && [ -n "$(find "$BUNDLE" -type d -name ingest-notion 2>/dev/null)" ]; then
    pass "runtime/$runtime: both notion skills present (OSS sees them)"
  else
    fail "runtime/$runtime: notion skills absent from OSS bundle"
  fi
  if [ -z "$(find "$BUNDLE" -name 'connector-notion*' 2>/dev/null)" ]; then
    pass "runtime/$runtime: no connector code leaks to OSS"
  else
    fail "runtime/$runtime: connector-notion code found in OSS bundle"
  fi
done

# 7. Connect pack is empty — every gated connector skill ships in the OSS base.
PACK_SKILLS=$(python3 -c "
import json
print(','.join(json.load(open('$ROOT/api/assets/connect-runtime-pack.json'))['skills']))
" 2>/dev/null)
if [ -z "$PACK_SKILLS" ]; then
  pass "connect pack: empty (gated skills live in the OSS base)"
else
  fail "connect pack: unexpected skill set" "$PACK_SKILLS"
fi

echo ""
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
